"""Render the homepage from curated JSON and fixed, reviewable Jekyll widgets.

Generated HTML remains static and usable with JavaScript disabled. Editorial data
is always escaped; Liquid markup comes exclusively from these source-controlled
templates and never from JSON content.
"""

import html

HEADER = "<!-- Generated by .github/scripts/generate_site_content.py; edit _data/home_content.json. -->"
HERO_TEMPLATE = "{%- assign languages = site.data.technologies | where: \"group\", \"Languages\" | first -%}\n<section class=\"hero\">\n  <div class=\"container hero__grid\">\n    <div class=\"hero__content\">\n      <p class=\"eyebrow\">@@eyebrow@@</p>\n      <h1 class=\"hero__title\">@@title@@</h1>\n      <p class=\"hero__tagline\">@@tagline@@</p>\n      <p class=\"hero__intro\">@@intro@@</p>\n      <div class=\"button-row\">\n        {% include link.html url=site.projects_url label=\"View Projects\" class=\"button button--primary\" arrow=true %}\n        {% include link.html url=site.data.social.profiles.github.url label=\"GitHub\" icon=\"github\" class=\"button button--secondary\" %}\n        {% include link.html url=\"/contact/\" label=\"Contact Me\" class=\"button button--ghost\" %}\n      </div>\n    </div>\n\n    <div class=\"hero__aside\">\n      {%- comment -%} With JavaScript, this card becomes a terminal (src/ts/terminal.ts). {%- endcomment %}\n      <div class=\"spec-card\" data-terminal data-terminal-data=\"{{ '/terminal.json' | relative_url }}?v={{ site.time | date: '%s' }}\">\n        <p class=\"spec-card__header\"><span>profile</span><span>{{ site.display_url }}</span></p>\n        <dl class=\"spec-card__list\">\n          <div class=\"spec-card__row\"><dt>name</dt><dd>{{ site.author.name }}</dd></div>\n          <div class=\"spec-card__row\"><dt>github</dt><dd>{{ site.author.username }}</dd></div>\n          <div class=\"spec-card__row\"><dt>community</dt><dd>@{{ site.author.community_username }}</dd></div>\n          <div class=\"spec-card__row\"><dt>focus</dt><dd>software · open source · developer tools</dd></div>\n          <div class=\"spec-card__row\"><dt>areas</dt><dd>android · web · games · ai/ml</dd></div>\n          <div class=\"spec-card__row\"><dt>languages</dt><dd>{{ languages.items | join: \" · \" | downcase }}</dd></div>\n        </dl>\n      </div>\n    </div>\n  </div>\n</section>\n"
WIDGETS = {
    "about": "    <div class=\"split\">\n      <p>@@about_0@@</p>\n      <p>@@about_1@@</p>\n    </div>\n    <p class=\"section-footer\">{% include link.html url=\"/about/\" label=\"More about me\" class=\"text-link\" arrow=true %}</p>\n",
    "focus": "    <ul class=\"feature-grid feature-grid--4\" role=\"list\">\n      {%- for area in site.data.focus %}\n      <li class=\"feature\">\n        {% include icon.html name=area.icon class=\"feature__icon\" %}\n        <h3 class=\"feature__title\">{{ area.title }}</h3>\n        <p class=\"feature__text\">{{ area.summary }}</p>\n      </li>\n      {%- endfor %}\n    </ul>\n    <p class=\"section-footer\">{% include link.html url=\"/developer/\" label=\"View the developer profile\" class=\"text-link\" arrow=true %}</p>\n",
    "technologies": "    {% include tech-list.html %}\n",
    "repos": "    {%- assign gh = site.data.github %}\n    {%- if gh and gh.featured.size > 0 %}\n    <ul class=\"repo-grid\">\n      {%- for name in gh.featured limit: 3 %}\n        {%- assign repo = gh.repositories | where: \"name\", name | first %}\n        {%- if repo %}\n      <li>{% include repo-card.html repo=repo %}</li>\n        {%- endif %}\n      {%- endfor %}\n    </ul>\n    <p class=\"section-footer link-row\">\n      {% include link.html url=site.projects_url label=\"All projects\" class=\"text-link\" arrow=true %}\n      {% include link.html url=site.data.social.profiles.github.url label=\"GitHub profile\" icon=\"github\" class=\"text-link\" %}\n    </p>\n    {%- else %}\n    <div class=\"callout\">\n      {% include icon.html name=\"github\" class=\"callout__icon\" %}\n      <div>\n        <h3 class=\"callout__title\">github.com/{{ site.author.username }}</h3>\n        <p class=\"callout__text\">Browse repositories, follow development, open issues, and suggest improvements. GitHub is the best place to see what I'm working on.</p>\n      </div>\n      {% include link.html url=site.data.social.profiles.github.url label=\"Visit GitHub\" class=\"button button--primary\" arrow=true %}\n    </div>\n    {%- endif %}\n",
    "blog": "    {%- if site.posts.size > 0 %}\n    <ul class=\"post-list\">\n      {%- for post in site.posts limit: 3 %}\n      <li>{% include post-card.html post=post %}</li>\n      {%- endfor %}\n    </ul>\n    {%- else %}\n    <p>The blog is ready for its first post.</p>\n    {%- endif %}\n    <p class=\"section-footer\">{% include link.html url=\"/blog/\" label=\"Read the blog\" class=\"text-link\" arrow=true %}</p>\n",
    "community": "    {% include profile-list.html items=site.data.social.community variant=\"card\" class=\"link-grid\" %}\n",
    "products": "    {% include profile-list.html group=\"products\" variant=\"card\" class=\"link-grid\" %}\n",
    "contact": "    <div class=\"contact-grid\">\n      {% include contact-card.html group=\"business\" %}\n      {% include contact-card.html group=\"support\" %}\n    </div>\n    <p class=\"section-footer\">{% include link.html url=\"/contact/\" label=\"All contact options\" class=\"text-link\" arrow=true %}</p>\n",
}
SECTION_IDS = tuple(WIDGETS)


def safe_text(value, context):
    if not isinstance(value, str) or not value.strip() or len(value) > 2000:
        raise ValueError(f"{context}: expected non-empty text up to 2000 chars")
    if any(ord(char) < 32 for char in value):
        raise ValueError(f"{context}: control character in text")
    # Prevent HTML and Liquid injection. Only curated WIDGETS may contain Liquid.
    return html.escape(value.strip(), quote=True).replace("{", "&#123;")


def validate(data):
    if not isinstance(data, dict) or set(data) != {"hero", "about_paragraphs", "sections"}:
        raise ValueError("home: expected hero, about_paragraphs, sections")
    hero = data["hero"]
    if not isinstance(hero, dict) or set(hero) != {"eyebrow", "title", "tagline", "intro"}:
        raise ValueError("home.hero: invalid keys")
    for key, value in hero.items():
        safe_text(value, "home.hero." + key)
    paragraphs = data["about_paragraphs"]
    if not isinstance(paragraphs, list) or len(paragraphs) != 2:
        raise ValueError("home.about_paragraphs: expected two paragraphs")
    for i, value in enumerate(paragraphs):
        safe_text(value, f"home.about_paragraphs[{i}]")
    sections = data["sections"]
    if not isinstance(sections, list) or len(sections) != len(SECTION_IDS):
        raise ValueError("home.sections: expected eight curated sections")
    seen = set()
    for i, section in enumerate(sections):
        if not isinstance(section, dict) or set(section) != {"id", "title", "lead"}:
            raise ValueError(f"home.sections[{i}]: expected id, title, lead")
        section_id = section["id"]
        if not isinstance(section_id, str) or section_id != SECTION_IDS[i] or section_id in seen:
            raise ValueError(f"home.sections[{i}]: unexpected, duplicated, or reordered widget")
        seen.add(section_id)
        safe_text(section["title"], f"home.sections[{i}].title")
        safe_text(section["lead"], f"home.sections[{i}].lead")


def render_hero(data):
    validate(data)
    rendered = HERO_TEMPLATE
    for key, value in data["hero"].items():
        rendered = rendered.replace("@@" + key + "@@", safe_text(value, "home.hero." + key))
    return HEADER + "\n" + rendered


def render_sections(data):
    validate(data)
    lines = [HEADER]
    for index, section in enumerate(data["sections"], start=1):
        css_class = "section section--surface" if index % 2 == 0 else "section"
        lines.extend([
            f'<section class="{css_class}">',
            '  <div class="container">',
            '    <div class="section-header">',
            f'      <h2 class="section-title"><span class="section-title__index" aria-hidden="true">{index:02d}</span>{safe_text(section["title"], "home.sections.title")}</h2>',
            f'      <p class="section-header__lead">{safe_text(section["lead"], "home.sections.lead")}</p>',
            '    </div>',
        ])
        widget = WIDGETS[section["id"]]
        if section["id"] == "about":
            for i, value in enumerate(data["about_paragraphs"]):
                widget = widget.replace("@@about_" + str(i) + "@@", safe_text(value, f"home.about_paragraphs[{i}]"))
        lines.extend([widget.rstrip("\n"), '  </div>', '</section>', ''])
    return "\n".join(lines).rstrip() + "\n"
